function nextWritingTipIndex(language:'es'|'en'){
 const tips=writingTips[language];
 try{const key=`tsukikage-last-tip-${language}`;const previous=Number(localStorage.getItem(key));const choices=tips.map((_,index)=>index).filter(index=>index!==previous);const selected=choices[Math.floor(Math.random()*choices.length)]??0;localStorage.setItem(key,String(selected));return selected;}catch{return Math.floor(Math.random()*tips.length);}
}
