const safeFilename = (v:string) => v.trim().replace(/[^\p{L}\p{N}-]+/gu,'-').replace(/^-|-$/g,'').toLowerCase() || 'tsukikage';
type SearchKind = 'chapter' | Entry['kind'];
type SearchResult = {id:string;kind:SearchKind;title:string;excerpt:string;chapterId?:string};
const escapeRegExp=(value:string)=>value.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
function searchSnippet(value:string,query:string){const text=value.replace(/\s+/g,' ').trim();const at=text.toLocaleLowerCase().indexOf(query.toLocaleLowerCase());if(at<0)return text.slice(0,120);const start=Math.max(0,at-58);const end=Math.min(text.length,at+query.length+86);return `${start?'…':''}${text.slice(start,end)}${end<text.length?'…':''}`;}
function searchProject(novel:Novel|undefined,phrase:string):SearchResult[]{const query=phrase.trim();if(!novel||!query)return[];const matches:SearchResult[]=[];for(const chapter of novel.chapters){const body=[htmlToText(chapter.text),chapter.synopsis||'',...(chapter.scenes||[]).flatMap(scene=>[scene.title,scene.description||'',htmlToText(scene.text)])].filter(Boolean).join(' ');if(`${chapter.title} ${body}`.toLocaleLowerCase().includes(query.toLocaleLowerCase()))matches.push({id:chapter.id,chapterId:chapter.id,kind:'chapter',title:chapter.title,excerpt:searchSnippet(body||chapter.title,query)});}for(const entry of novel.entries||[]){const body=[entry.name,entry.date||'',entry.description||''].filter(Boolean).join(' ');if(body.toLocaleLowerCase().includes(query.toLocaleLowerCase()))matches.push({id:entry.id,kind:entry.kind,title:entry.name,excerpt:searchSnippet(body,query)});}return matches;}
function HighlightedText({text,term}:{text:string;term:string}){if(!term.trim())return <>{text}</>;const parts=text.split(new RegExp(`(${escapeRegExp(term.trim())})`,'ig'));return <>{parts.map((part,index)=>part.toLocaleLowerCase()===term.trim().toLocaleLowerCase()?<mark key={index}>{part}</mark>:part)}</>;}
function escapeHtmlAttribute(value:string){return value.replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[char]||char));}
function fullChapterHtml(scenes:Scene[]){return scenes.map((scene,index)=>`${index?`<div data-tsukikage-scene-break="true" data-scene-id="${escapeHtmlAttribute(scene.id)}" data-scene-title="${escapeHtmlAttribute(scene.title)}"></div>`:''}${scene.text||'<p></p>'}`).join('');}
function splitFullChapterHtml(html:string,scenes:Scene[]){if(!scenes.length)return[];const root=new DOMParser().parseFromString(html,'text/html').body;const content=new Map(scenes.map(scene=>[scene.id,'']));let activeId=scenes[0].id;let current='';let nextIndex=1;const save=()=>content.set(activeId,current);for(const node of Array.from(root.childNodes)){if(node instanceof HTMLElement&&node.hasAttribute('data-tsukikage-scene-break')){save();const next=node.getAttribute('data-scene-id');activeId=next&&content.has(next)?next:(scenes[nextIndex]?.id||activeId);nextIndex=Math.max(nextIndex,scenes.findIndex(scene=>scene.id===activeId)+1);current='';continue;}current+=node instanceof HTMLElement?node.outerHTML:node.nodeType===Node.TEXT_NODE?escapeHtmlAttribute(node.textContent||''):'';}save();return scenes.map(scene=>({...scene,text:content.get(scene.id)||''}));}
const commonCapitalizedWords=new Set('a an and as at after again all also although am among an any are around as because before below between both but by can could did do does during each either else ever every few for from further had has have he her here hers herself him himself his how however i if in into is it its itself just least less like may me might more most must my myself neither no nor not of off on once one only or other ought our ours ourselves out over own per same several she should since so some such than that the their theirs them themselves then there these they this those through to too under until up very was we were what when where whether which while who whom why will with without would you your yours yourself yourselves el la las los un una unos unas al de del en y o u a ante bajo con contra desde durante entre hacia hasta para por según sin sobre tras como es son fue era han había hay no sí más muy pero que quien quienes cuando donde así este esta estos estas ese esa esos esas su sus se le les lo por porque aunque cada también luego entonces antes después ya ayer hoy nunca siempre puede pueden ser lo misma mismo todo toda todos todas'.normalize('NFD').replace(/[\u0300-\u036f]/g,'').split(/\s+/));
function possibleNames(novel:Novel|undefined){if(!novel)return[];const listed=new Set((novel.entries||[]).map(entry=>entry.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase()));const words=novel.chapters.flatMap(chapter=>htmlToText(chapter.text).match(/\b[\p{Lu}][\p{Ll}]{2,}\b/gu)||[]);return [...new Set(words.filter(word=>{const normalized=word.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase();return !listed.has(normalized)&&!commonCapitalizedWords.has(normalized)}))].slice(0,12);}

